    add     -0x10, sp

DrawBitmapFast_entry:
    mov     d0, d2                          # d2 = bitmap index
    mov     a0, a2                          # a2 = &point
    call    IsDrawTask_entry, 0, 0x10
    cmp     0, d0
    beq     DrawBitmapFast_Deferred         # not the draw task: queue it
    mov     (DrawEnable), d0
    cmp     0, d0
