    add     0x10, d0
    mov     d0, (0x48, sp)
    mov     (0x18, sp), d0
    mov     PICTURE_PLANE2, a2
    add     0x18, d0
    mov     d0, (0x44, sp)
    mov     a0, d0
    add     0x80, d0
    mov     d0, (0x14, sp)
    add     8, d0
    mov     d0, (0x24, sp)
    mov     (0x14, sp), d0
    add     0x10, d0
    mov     d0, (0x20, sp)
    mov     (0x14, sp), d0
    add     0x18, d0
    mov     d0, (0x28, sp)
    movhu   (0x5a, sp), d0
    exth    d0
    mov     d0, (0x38, sp)
    movhu   (0x5c, sp), d0
    exth    d0
    mov     d0, (0x34, sp)
    movhu   (0x5e, sp), d0
    exth    d0
    mov     d0, (0x30, sp)
    movhu   (0x58, sp), d0
    exth    d0
    mov     d0, (0x3c, sp)
    movhu   (0x5e, sp), d0
    exth    d0
    mov     d0, (0x2c, sp)
