    mov     a3, a0
    mov     (0x1c, sp), d0
    call    BmpUnpackRow_entry, [d2,d3,a2,a3], 0x30  # unpack in place to one byte per pixel (8 bpp: left as is)
    mov     (0x20, sp), d1
    clr     d0
    cmp     d0, d1
    ble     Draw2BpFile_Impl_CopyRow        # width <= 0
