    setlb
    movbu   (d0, a3), d1
    add     0x20, d1                        # BMP index n -> colour 0x20 + n
    movbu   d1, (d0, a3)
    mov     (0x20, sp), d1
    inc     d0
    exth    d0
    cmp     d1, d0
    llt                                     # next pixel while i < width

Draw2BpFile_Impl_CopyRow:
    mov     a2, a0
    mov     a3, a1
    mov     (0x28, sp), d0
    call    memcpy_entry, [a2,a3], 8        # memcpy(dest, row buffer, width): width is not clipped
