    mov     (0x1c, sp), d1
    inc     d2
    add     d1, d0
    mov     d0, (0x38, sp)                  # next file row += stride
    exth    d2
    mov     0x280, d0
    sub     d0, a2                          # dest one framebuffer row up
    cmp     d3, d2
    blt     Draw2BpFile_Impl_RowLoop        # next row while row < rows to draw

