    mov     (0x30, sp), a0
    mov     (0x454, sp), d0
    movhu   (a0), d1
    mov     sp, a0
    exth    d1
    add     d0, d1
    add     -1, d1
    movhu   d1, (0x47a, sp)                 # rect.bottom = y + biHeight - 1
    add     0x474, a0                       # a0 = &rect
    call    SetChangeRect, 0, 0

