    call    PanelTickWait6, 0, 0
    call    PanelTickWait6, 0, 0
    call    PanelTickWait6, 0, 0
    call    PanelTickWait6, 0, 0
    call    PanelTickWait6, 0, 0
    call    PanelWaitLinkIdle_entry, 0, 8
    mov     0xea, d0
    clr     d1
    call    PanelTxKick_entry, [d2,d3], 0x14
    call    PanelTickWait6, 0, 0
    call    PanelTickWait6, 0, 0
    call    PanelTickWait6, 0, 0
    call    PanelTickWait6, 0, 0
    call    PanelTickWait6, 0, 0
    call    PanelWaitLinkIdle_entry, 0, 8
    mov     0x20, d0
    mov     0x10, d1
    call    PanelTxKick_entry, [d2,d3], 0x14
    call    PanelTickWait6, 0, 0
    call    PanelTickWait6, 0, 0
    call    PanelWaitLinkIdle_entry, 0, 8
    mov     0xe3, d0
