    call    func_4857BE97, 0, 0x14
    call    func_48579255, 0, 8
    mov     -1, d0
    movhu   d0, (0x50083bac)
    movhu   d0, (0x50083bae)
    movhu   d0, (0x50083bb0)
    movhu   d0, (0x50083bb2)
