    movbu   d0, (0x50083bb6)
    movbu   d0, (0x50083bb7)
    movbu   d0, (0x50083bb8)
    movbu   d0, (0x50083bb9)
    movbu   d0, (0x50083bba)
    movbu   d0, (0x50083bbf)
    movbu   d0, (0x50083bc4)
    movbu   d0, (0x50083bc5)
    mov     0x4868da64, a0
    movbu   (a0), d0
    mov     0x50083bc6, a1
    movbu   d0, (a1)
    movbu   (1, a0), d0
    movbu   d0, (1, a1)
    ret     0, 0xc
