    not     d0
    mov     d0, (0, sp)
    mov     (8, sp), d0
    not     d0
    mov     d0, (0x10, sp)
    setlb
    extbu   d3
    mov     (4, sp), d0
    mov     0x485865ec, a0
    movbu   (d3, a0), d1
    and     d0, d1
    beq     loc_4C0056FC
    movbu   (0x30, sp), d0
    mov     d3, d2
    mov     d0, a0
    asl2    d2
    mov     a0, a1
    mov     0x53a, d0
    add     a2, d0
    add     d2, d0
    add     d0, a1
    movbu   (a1), d1
    mov     (8, sp), d0
    or      d0, d1
    movbu   d1, (a1)
