    add     -0x10, sp
    mov     0x130, d1
    mov     0x500ce404, a0
    mov     d0, d2
    extbu   d0
    nop
    nop
    mulu    d1, d0
    mov     (d0, a0), a0
    movbu   (0x44, a0), d0
    and     0x0f, d0
    cmp     0, d0
    bge     loc_4C00CFAE
    ret     [d2], 0x14
loc_4C00CFAE:
    cmp     0xb, d0
    ble     loc_4C00CFB5
    ret     [d2], 0x14
loc_4C00CFB5:
    asl2    d0
    mov     0x48586f28, a0
    mov     (d0, a0), a0
    jmp     (a0)
    extbu   d2
    clr     d1
    mov     d2, d0
    call    TgPartEditLfoLoadA_entry, [d2,a2], 8
    ret     [d2], 0x14
    extbu   d2
    mov     1, d1
    mov     d2, d0
    call    TgPartEditLfoLoadA_entry, [d2,a2], 8
    ret     [d2], 0x14
    extbu   d2
    mov     2, d1
    mov     d2, d0
    call    TgPartEditLfoLoadA_entry, [d2,a2], 8
    ret     [d2], 0x14
    extbu   d2
